loadProject=async function(p){S.space=clone(p.search_space||{schema_version:1,variables:[],nodes:{},global_constraints:{},local_constraints:[]});S.modulePath=[];S.selection=[];await oldLoadProject(p);};
function rootGraph(){let ir=clone(S.ir);for(let i=S.modulePath.length-1;i>=0;i--){const f=S.modulePath[i],parent=clone(f.ir),node=parent.nodes.find(n=>n.id===f.id);node.module=ir;ir=parent;}return ir;}
save=async function(){const ir=rootGraph(),positions=S.modulePath.length?S.modulePath[0].positions:S.positions;const p=await api('/projects/'+S.project.id,'PUT',{name:S.project.name,ir,dataset_id:S.project.dataset_id,layout:positions,search_space:S.space});S.project=p;S.projects=S.projects.map(x=>x.id===p.id?p:x);saved();const revision=$('.studio-title p');if(revision)revision.textContent=(S.modulePath.length?'Module editor':'Architecture Studio')+' · '+S.ir.nodes.length+' blocks · v'+p.revision;toast('Saved as version '+p.revision);};
const OP_NAMES={Input:'Image Input',Conv2d:'Convolution',ConvBlock:'Conv Block',ResidualBlock:'Residual Block',BatchNorm2d:'Batch Norm',MaxPool2d:'Max Pool',AvgPool2d:'Average Pool',AdaptiveAvgPool2d:'Global Average Pool',PatchEmbedding:'Patch Embedding',PositionalEmbedding:'Position Embedding',PositionalEncoding:'Position Encoding',MultiHeadAttention:'Self Attention',TransformerEncoder:'Encoder Block',TransformerStack:'Transformer Stack',FeedForward:'Feed Forward',ClassToken:'Class Token',TokenPooling:'Token Pooling',LayerNorm:'Layer Norm',Linear:'Linear',Flatten:'Flatten',Module:'Reusable Module'};
const DEFAULTS={Conv2d:{out_channels:16,kernel_size:3,stride:1,padding:1},ConvBlock:{out_channels:16,kernel_size:3,stride:1,activation:'GELU',norm:'BatchNorm'},ResidualBlock:{out_channels:16,kernel_size:3,stride:1,padding:1},MaxPool2d:{kernel_size:2},AvgPool2d:{kernel_size:2},Linear:{out_features:3},Dropout:{p:.1},PatchEmbedding:{patch_size:4,embed_dim:64},Embedding:{vocab_size:128,embed_dim:64},MultiHeadAttention:{num_heads:4,qkv_bias:true,attn_dropout:.1,proj_dropout:.1,attention_type:'MHA'},TransformerEncoder:{num_heads:4,ffn_ratio:4,dropout:.1,activation:'GELU',qkv_bias:true},TransformerStack:{depth:2,num_heads:4,ffn_ratio:4,dropout:.1,activation:'GELU',qkv_bias:true},FeedForward:{expansion_ratio:4,activation:'GELU',dropout:.1},TokenPooling:{mode:'cls'}};
