 'studio-tools':studioTools,'import-code':codeImportModal,'smart-edit':smartEditModal,'quick-find':quickFind,'architecture-diff':architectureDiff,
 'inspect-node':()=>{S.inspectNode=nodePath(S.selected);if(inspectionJob()){if($('#modal').open)$('#modal').close();navigate('inspect')}else inspectionConfigure('debug')},
