 'pipeline-save':async()=>{const saved=await api('/pipelines','POST',{dataset_id:dataset().id,steps:S.pipeline,seed:S.pipelineSeed||42,name:(S.ir.name||'Model')+' pipeline'});await api('/projects/'+S.project.id+'/pipeline','POST',{dataset_id:dataset().id,steps:S.pipeline,seed:S.pipelineSeed||42});S.project.data_pipeline=clone(S.pipeline);S.pipelines=await api('/pipelines');toast('Pipeline saved and applied to subsequent jobs')},
