 'figure-edit':openFigure,'figure-svg':()=>figureDownload('svg'),'figure-png':()=>figureDownload('png'),'figure-pdf':()=>figureDownload('pdf'),'figure-json':()=>figureDownload('json'),
 'figure-save':async()=>{await api('/figures','POST',{document:S.figure,name:S.figureName||'Architecture figure',project_id:S.project.id});toast('Editable scene saved')},
 'figure-open':async()=>{const fs=await api('/figures');modal('Saved editable figures',fs.map(f=>`<button class="project-row" data-open-figure="${f.id}"><strong>${esc(f.name)}</strong><small>${new Date(f.created_at*1000).toLocaleString()}</small></button>`).join('')||'<p>No saved figures yet.</p>');$$('[data-open-figure]').forEach(b=>b.onclick=()=>{const f=fs.find(f=>f.id===b.dataset.openFigure);S.figure=clone(f.document);S.figureName=f.name;S.figureSelection=[];S.figureUndo=[];$('#modal').close();navigate('figure')})},
 'figure-undo':()=>{if(S.figureUndo.length){S.figure=S.figureUndo.pop();S.figureSelection=[];drawFigure();figureInspector()}},
 'figure-add-text':()=>{figureHistory();S.figure.objects.push(['text',100,110,'Your annotation',20,'#34463a',500,'start']);S.figureSelection=[S.figure.objects.length-1];drawFigure();figureInspector()},
 'figure-add-card':()=>{figureHistory();S.figure.objects.push(['rect',100,150,200,100,'#e9eff8','#c5cdd8',8,1]);S.figureSelection=[S.figure.objects.length-1];drawFigure();figureInspector()},
