 'figure-group':()=>{S.figure.groups=(S.figure.groups||[]).filter(g=>!g.some(i=>S.figureSelection.includes(i)));S.figure.groups.push([...S.figureSelection]);toast('Elements grouped. Click one to move the group.')},
 'figure-select-group':()=>{const el=$('[data-figure="'+S.figureSelection.at(-1)+'"]');if(!el)return;const box=el.getBBox();S.figureSelection=$$('[data-figure]').filter(e=>{const b=e.getBBox();return b.x>=box.x-10&&b.y>=box.y-10&&b.x+b.width<=box.x+box.width+10&&b.y+b.height<=box.y+box.height+10}).map(e=>Number(e.dataset.figure));drawFigure();figureInspector()},
