const studioInit03=init;init=async function(){S.algorithms=await api('/algorithms').catch(()=>null);const nav=$('nav');if(nav){nav.insertAdjacentHTML('beforeend',`<button class="nav-item" data-page="inspect">${icon('activity')}<span>Tensor & Performance</span></button><button class="nav-item" data-page="pipeline">${icon('database')}<span>Data Pipeline</span></button><button class="nav-item" data-page="optimization">${icon('layers')}<span>Model Optimization</span></button>`);$$('[data-page]').forEach(b=>b.onclick=()=>{if(b.dataset.page==='pipeline')api('/pipelines').then(p=>{S.pipelines=p;render()});navigate(b.dataset.page)})}await studioInit03();};

const studioProgress03=jobProgress;jobProgress=function(j){const title={debug:'Tensor Debugger',profile:'Performance Profiler',optimize:'Model Optimization'}[j.kind];return title?studioProgress03(j).replace(/Proxy analysis/gi,title):studioProgress03(j)};
const studioRuntime03=runtimeStrip;runtimeStrip=function(j){if(!j||!['debug','profile','optimize'].includes(j.kind))return studioRuntime03(j);return `<div class="runtime-strip"><div class="runtime-item"><small>DEVICE</small><strong>${esc(j.device||j.payload.device)}</strong></div><div class="runtime-item"><small>GPU / CPU</small><strong style="font-size:11px">${esc(j.device_name||'Queued')}</strong></div><div class="runtime-item"><small>MEMORY / PEAK</small><strong>${j.memory_peak_mb==null?'—':fmt(j.memory_current_mb,1)+' / '+fmt(j.memory_peak_mb,1)+' MB'}</strong></div><div class="runtime-item"><small>PROCESS</small><strong>${j.worker_pid||'—'}</strong></div></div>`};
async function showPairDiff(left,right,beforeLabel='Before',afterLabel='After'){const d=await api('/architectures/diff','POST',{left,right});modal('Architecture Diff',`<div class="diff-counts"><span class="green">+${d.added.length} nodes</span><span class="red">−${d.removed.length} nodes</span><span>${d.changed.length} changed</span><span>Edges +${d.edges_added.length} / −${d.edges_removed.length}</span></div><div class="diff-columns"><div><h3>${esc(beforeLabel)} · ${compact(d.before.params)} params</h3>${miniDiffGraph(left,'before',d)}</div><div><h3>${esc(afterLabel)} · ${compact(d.after.params)} params</h3>${miniDiffGraph(right,'after',d)}</div></div><div class="diff-details">${d.changed.map(n=>`<details><summary>${esc(n.id)} · ${Object.keys(n.fields).join(', ')}</summary><pre>${esc(JSON.stringify(n.fields,null,2))}</pre></details>`).join('')}</div>`);}
ACTIONS['compare-candidates']=async()=>{const cs=currentSearch()?.candidates||[];const selected=cs.filter(c=>S.compare.includes(c.id)),pair=selected.length?selected:cs.slice(0,2);if(pair.length!==2)throw Error('Select two candidates');await showPairDiff(pair[0].ir,pair[1].ir,pair[0].id.slice(0,8),pair[1].id.slice(0,8));};
ACTIONS['template-diff']=async()=>{const j=currentSearch(),c=j?.candidates.find(c=>c.id===S.candidate)||j?.candidates[0];if(!c)throw Error('Select a candidate');await showPairDiff(j.payload.ir,c.ir,'Original template','Candidate');};

