function compareGraph04(ir,other){const map=new Map(other.nodes.map(n=>[n.id,n]));const changed=ir.nodes.filter(n=>map.has(n.id)&&JSON.stringify(n)!==JSON.stringify(map.get(n.id))).map(n=>({id:n.id}));return miniDiffGraph(ir,'after',{changed,removed:[],added:ir.nodes.filter(n=>!map.has(n.id)).map(n=>n.id),edges_added:[],edges_removed:[]})}
function draft04(){return {project_id:S.project.id,ir:rootGraph(),search_space:clone(S.space)}}
function panel04(title,body){return `<section class="panel"><div class="panel-header"><h2>${title}</h2></div><div class="panel-body">${body}</div></section>`}
function copilotSettings(){modal('Connect your model',`<form id="agent-config"><p>Your key stays in this server session for eight hours. It is never saved to projects, browser storage or exports.</p><label class="field"><span>API protocol</span><select name="protocol"><option value="responses" ${S.agentConfig?.protocol==='responses'?'selected':''}>Responses API</option><option value="chat" ${S.agentConfig?.protocol==='chat'?'selected':''}>OpenAI-compatible Chat Completions</option></select></label>${field('API base URL','endpoint',S.agentConfig?.endpoint||'https://api.openai.com/v1','url')}${field('Model ID','model',S.agentConfig?.model||'','text','required placeholder="Enter a tool-calling model ID"')}<label class="field"><span>API key</span><input name="api_key" type="password" autocomplete="off" required placeholder="Your provider API key"></label><p class="field-note">Generating a plan sends the current architecture, configuration and aggregate metrics to your chosen provider. Dataset samples are excluded.</p><button class="btn primary" type="submit">Connect for this session</button><button class="btn" id="agent-forget" type="button">Forget key</button></form>`);$('#agent-forget').onclick=fire(async()=>{await api('/copilot/config','DELETE');S.agentConfig={configured:false};$('#modal').close();render();toast('Session key cleared')});$('#agent-config').onsubmit=fire(async e=>{e.preventDefault();const f=e.currentTarget;try{S.agentConfig=await api('/copilot/config','POST',Object.fromEntries(new FormData(f)));$('#modal').close();render();toast('Provider configured')}finally{f.querySelector('[name=api_key]').value=''}});}
function agentExample(text){S.agentPrompt=text;$('#agent-prompt').value=text;$('#agent-prompt').focus()}
function planPreview04(p){const c=p.compiled;if(!c)return '';const changes=c.diff;return `<div class="agent-plan"><div class="agent-plan-title"><span class="eyebrow">${p.status==='preview'?'REVIEW REQUIRED':'PLAN '+esc(p.status.toUpperCase())}</span><h2>${esc(c.plan.title)}</h2><small class="field-note">${p.origin==='agent'?'Copilot agent · validated tool plan':'Manual plan editor · validated structured plan'}</small><p>${esc(c.plan.rationale)}</p></div><div class="agent-stats"><span>${changes.changed?.length||changes.modified?.length||0} changed nodes</span><span>${c.search_after.variables?.length||0} search variables</span><span>${c.jobs.length} compute actions${p.status==='preview'?' on approval':''}</span><span>${compact(c.analysis.params)} parameters</span></div><div class="agent-diff-grid"><div><h3>Current draft</h3>${compareGraph04(c.before,c.after)}</div><div><h3>Proposed architecture</h3>${compareGraph04(c.after,c.before)}</div></div><div class="agent-steps">${c.plan.steps.map((s,i)=>`<div><b>${String(i+1).padStart(2,'0')}</b><span><strong>${esc(s.action)} ${esc(s.node_id)} ${esc(s.parameter)}</strong><code>${esc(s.value_json)}</code></span></div>`).join('')}</div>${c.space_summary?`<p class="field-note">${c.space_summary.theoretical_combinations??c.space_summary.combinations??'—'} theoretical combinations · ${c.space_summary.legal_combinations} legal combinations in static estimate</p>`:''}${[...c.plan.assumptions,...c.warnings].map(w=>`<p class="agent-warning">${esc(w)}</p>`).join('')}${c.jobs.map(j=>`<div class="agent-job"><strong>${esc(j.kind)}</strong><span>${esc(j.payload.device)} · ${j.kind==='search'?j.payload.strategy+' / '+j.payload.count+' candidates':j.kind==='train'?j.payload.epochs+' epochs / batch '+j.payload.batch_size:j.payload.inspect_batch+' samples'}</span></div>`).join('')}<details><summary>Agent tool trace & structured plan</summary><pre class="tensor-values">${esc(JSON.stringify({trace:p.trace,plan:c.plan},null,2))}</pre></details><div class="agent-plan-actions">${p.status==='preview'?`<button class="btn primary" id="agent-apply">Approve & apply${c.jobs.length?' / queue tasks':''}</button><button class="btn" id="agent-canvas">Preview on canvas</button><button class="btn" id="agent-discard">Discard</button>`:`<span class="badge green">${esc(p.status)}</span>${(p.job_ids||[]).map(id=>`<button class="btn small" data-agent-job="${id}">Open run ${id.slice(0,8)}</button>`).join('')}`}</div><p class="field-note">Approval saves a new architecture version. Compute runs in local workers. Any later draft change requires a new preview.</p></div>`}
function renderCopilot(){const a=S.agentPreview;$('#page').innerHTML=heading('UNDERSTAND → PREVIEW → APPLY','Architecture Copilot','Describe the change. Inspect the plan. Keep control.',btn(S.agentConfig?.configured?'Provider settings':'Connect API key','agent-settings','settings'))+`<div class="page-content agent-layout"><div class="stack">${panel04('Your engineering brief',`<form id="agent-request"><div class="tabs"><button type="button" data-agent-mode="architecture" class="tab ${S.agentMode==='architecture'?'active':''}">Design & search</button><button type="button" data-agent-mode="optimization" class="tab ${S.agentMode==='optimization'?'active':''}">Optimization assistant</button></div><textarea id="agent-prompt" rows="7" placeholder="Describe what to change in your current model…">${esc(S.agentPrompt)}</textarea><div class="agent-compose-footer"><span>${S.agentConfig?.configured?esc(S.agentConfig.model):'Bring your own API key'}</span><button type="submit" class="btn primary" ${S.agentBusy?'disabled':''}>${S.agentBusy?'Planning…':'Generate reviewable plan'}</button></div></form><div class="agent-examples"><button data-example="Make the Encoder depth searchable from 4 to 12 and attention heads 4, 8 or 16. Limit parameters to 50M. Run Bayesian GP-UCB for up to 100 candidates and measure latency on cuda:0.">Search a ViT</button><button data-example="Help reduce peak GPU memory by 30%. First inspect matching real measurements; propose AMP or smaller micro-batches with accumulation. Preview the changes and explain what needs actual evaluation to verify quality.">Reduce memory</button><button data-example="Read the current model and search space. Suggest a small, valid local architecture improvement and preview it without starting compute.">Improve this model</button></div>`)}${panel04('Connected context',`<div class="context-list"><span>Model</span><strong>${esc(S.project.name)}</strong><span>Draft</span><strong>${rootGraph().nodes.length} top-level nodes</strong><span>Search space</span><strong>${S.space.variables?.length||0} variables</strong><span>Dataset</span><strong>${esc(dataset()?.name||'None selected')}</strong><span>Compute</span><strong>${esc(S.system.devices?.map?.(d=>d.id).join(', ')||'Local CPU / CUDA')}</strong></div><p class="field-note">The agent uses validated tools. It can propose architecture edits, search domains and compute jobs; it cannot run arbitrary Python.</p><button class="btn small" id="agent-inspect-context">Inspect sent context</button>`)}<details class="panel panel-body"><summary>Structured plan editor</summary><p class="field-note">Build a plan manually without an API key. This is a deterministic compiler preview, not an AI response.</p><textarea id="agent-manual" rows="12" class="source-editor">${esc(JSON.stringify({title:'Profile the current architecture',rationale:'Establish a real runtime baseline before optimization.',assumptions:[],warnings:[],steps:[{action:'run',node_id:'',parameter:'profile',value_json:'{"device":"auto","inspect_batch":4}'}]},null,2))}</textarea><button class="btn" id="agent-manual-preview">Validate & preview</button></details>${S.agentMode==='optimization'?outcomePanel04():''}<div id="agent-history"></div></div><div class="stack">${a?planPreview04(a):`<div class="agent-empty"><div class="agent-orb">✳</div><span class="eyebrow">YOUR MODEL, WITH INTENT</span><h2>A plan you can inspect.</h2><p>Changes appear here before they touch your architecture.<br>Every task, constraint and assumption stays visible.</p><div class="agent-flow"><span>Read context</span>→<span>Compile</span>→<span>Review</span>→<span>Apply</span></div></div>`}</div></div>`;
$$('[data-agent-job]').forEach(b=>b.onclick=()=>{const j=S.jobs.find(j=>j.id===b.dataset.agentJob);if(!j)return toast('Worker is starting; refresh shortly');if(j.kind==='train'){S.trainJob=j.id;navigate('training')}else if(['profile','debug'].includes(j.kind)){S.inspectionJob=j.id;navigate('inspect')}else if(j.kind==='optimize'){S.optimizationJob=j.id;navigate('optimization')}else{S.searchJob=j.id;navigate('search')}});bindOutcome04();$('#agent-prompt').oninput=e=>S.agentPrompt=e.target.value;$$('[data-agent-mode]').forEach(b=>b.onclick=()=>{S.agentMode=b.dataset.agentMode;renderCopilot();bindActions()});$$('[data-example]').forEach(b=>b.onclick=()=>agentExample(b.dataset.example));$('#agent-request').onsubmit=fire(async e=>{e.preventDefault();if(!S.agentConfig?.configured)return copilotSettings();S.agentBusy=true;render();try{S.agentPreview=await api('/copilot/plan','POST',{...draft04(),prompt:S.agentPrompt,mode:S.agentMode});toast('Plan compiled. Review before applying.')}finally{S.agentBusy=false;render()}});$('#agent-inspect-context').onclick=fire(async()=>{const c=await api('/copilot/context','POST',draft04());modal('Context sent to your provider',`<pre class="tensor-values">${esc(JSON.stringify(c,null,2))}</pre>`)});$('#agent-manual-preview').onclick=fire(async()=>{S.agentPreview=await api('/copilot/preview','POST',{...draft04(),plan:JSON.parse($('#agent-manual').value)});render()});$('#agent-apply')?.addEventListener('click',fire(async()=>{const r=await api('/copilot/plans/'+a.id+'/apply','POST',{confirm:true,ir:rootGraph(),search_space:S.space});S.agentPreview={...a,status:'applied',job_ids:r.job_ids};S.agentCanvasPreview=null;await loadProject(r.project);navigate('copilot');toast('New version saved'+(r.job_ids.length?' · '+r.job_ids.length+' jobs queued':''))}));$('#agent-discard')?.addEventListener('click',fire(async()=>{await api('/copilot/plans/'+a.id+'/discard','POST');S.agentPreview=null;S.agentCanvasPreview=null;render()}));$('#agent-canvas')?.addEventListener('click',()=>{S.agentCanvasPreview=a;navigate('architecture')});api('/copilot/plans?project_id='+S.project.id).then(rows=>{if(!$('#agent-history'))return;$('#agent-history').innerHTML=panel04('Plan history',rows.slice(0,8).map(p=>`<button class="project-row" data-plan-history="${p.id}"><strong>${esc(p.compiled.plan.title)}</strong><small>${esc(p.origin)} · ${esc(p.status)}</small></button>`).join('')||'<p class="field-note">No plans yet.</p>');$$('[data-plan-history]').forEach(b=>b.onclick=()=>{S.agentPreview=rows.find(p=>p.id===b.dataset.planHistory);render()})}).catch(()=>{});}
async function refreshModels04(){[S.ecosystemCatalog,S.modelAssets,S.operatorRegistry]=await Promise.all([api('/ecosystem/catalog'),api('/ecosystem/assets'),api('/operators')])}
function modelImportModal(provider,model){modal('Import '+model,`<form id="ecosystem-import"><p>Input: ${dataset().shape.join(' × ')} · ${esc(dataset().name)}</p><p class="field-note">The importer probes the real model and preserves unsupported internals as protected blocks. Imported weights are saved as a local snapshot.</p><label class="checkbox-field"><input name="pretrained" type="checkbox">Download & use pretrained weights</label><label class="checkbox-field"><input name="allow_download" type="checkbox">Allow this import to download public model files</label><p class="field-note">A different task classifier may be newly initialized. Importing weights does not imply task accuracy. Hugging Face adapters never enable remote Python code.</p><button type="submit" class="btn primary">Import in worker</button></form>`);$('#ecosystem-import').onsubmit=fire(async e=>{e.preventDefault();const f=new FormData(e.currentTarget);if(provider==='huggingface'&&!f.has('allow_download'))throw Error('Confirm the public configuration download for Hugging Face');const j=await api('/ecosystem/import','POST',{project_id:S.project.id,provider,model,pretrained:f.has('pretrained'),allow_download:f.has('allow_download')});S.modelImportJob=j.id;$('#modal').close();navigate('ecosystem');toast('Import queued')});}
function renderEcosystem(){const j=S.jobs.find(j=>j.id===S.modelImportJob);$('#page').innerHTML=heading('MODELS THAT ALREADY EXIST','Model Ecosystem','Preserve real weights. Explore supported boundaries.',btn('Refresh assets','refresh-models','refresh'))+`<div class="page-content">${j?panel04('Latest import',`${badge(j.status)} <code>${j.id.slice(0,8)}</code>${j.error?`<p class="agent-warning">${esc(j.error)}</p>`:''}${j.result?.asset?`<p>${esc(j.result.asset.model)} · ${esc(j.result.asset.weight_status)}</p><button class="btn primary" data-open-model="${j.result.asset.id}">Preview imported architecture</button>`:''}`):''}<div class="ecosystem-grid">${(S.ecosystemCatalog||[]).map(p=>panel04(p.provider,`<span class="badge ${p.installed?'green':'orange'}">${p.installed?'Adapter installed':'Install optional dependency'}</span>${p.models.map(m=>`<div class="ecosystem-model"><div><strong>${esc(m.id)}</strong><p>${esc(m.description)}</p></div><button class="btn small" data-model-provider="${p.provider}" data-model-name="${esc(m.id)}" ${p.installed?'':'disabled'}>Import</button></div>`).join('')}`)).join('')}</div><div class="section-gap">${panel04('Local model snapshots',(S.modelAssets||[]).map(m=>`<div class="ecosystem-model"><div><strong>${esc(m.model)}</strong><p>${esc(m.provider)} · ${esc(m.weight_status)} · ${compact(m.params)} parameters</p></div><button class="btn" data-open-model="${m.id}">Open preview</button></div>`).join('')||'<p>No imports yet.</p>')}</div><p class="field-note">ResNet exposes stage boundaries for local replacement and search. Other adapters currently preserve a protected backbone with a task head. BERT / GPT-2 use token classification datasets; decoder generation and UNet are outside this adapter release.</p></div>`;$$('[data-model-provider]').forEach(b=>b.onclick=()=>modelImportModal(b.dataset.modelProvider,b.dataset.modelName));$$('[data-open-model]').forEach(b=>b.onclick=fire(async()=>{await refreshModels04();const m=S.modelAssets.find(m=>m.id===b.dataset.openModel);if(!m)throw Error('Refresh assets after the worker completes');modal('Review imported model',`<h3>${esc(m.model)}</h3><p>${esc(m.weight_status)}</p>${compareGraph04(m.ir,rootGraph())}${m.notes.map(n=>`<p class="field-note">${esc(n)}</p>`).join('')}<p class="field-note">Applying replaces the current draft. Saving creates a version; original pretrained assets stay available.</p><button class="btn primary" id="apply-model-import">Apply to draft</button>`);$('#apply-model-import').onclick=fire(async()=>{history();S.ir=clone(m.ir);S.modulePath=[];S.space={schema_version:1,nodes:{},variables:[],global_constraints:{},local_constraints:[]};S.positions={};S.selected=S.ir.nodes[0].id;setDirty();await analyze(false);$('#modal').close();navigate('architecture');setTimeout(()=>ACTIONS.fit(),30)})}));}
async function insertOperator04(m){const r=await api('/graph/edit','POST',{ir:S.ir,action:'insert',node_id:S.selected||'input',op:'CustomOperator',config:{operator_id:m.id,parameters:m.parameters}});history();S.ir=r.ir;S.selected=r.inserted;S.positions={};setDirty();await analyze(false);navigate('architecture')}
function renderOperators(){$('#page').innerHTML=heading('EXTEND YOUR COMPONENTS','Custom Operator SDK','Register a trusted PyTorch operator with a verified tensor contract.',btn('Refresh registry','refresh-models','refresh'))+`<div class="page-content split-layout"><div class="stack">${panel04('Register & probe',`<form id="operator-register">${field('Operator name','name','Channel Gate','text','required')}${field('Input shape, without batch','input_shape','8,32,32','text')}${field('Constructor parameters (JSON)','parameters','{"channels":8}','text')}<label class="field"><span>Python source · class Operator(nn.Module)</span><textarea name="source" rows="17" class="source-editor" spellcheck="false">${esc(S.operatorRegistry?.example||'')}</textarea></label><label class="checkbox-field"><input name="trusted_code" required type="checkbox">I trust this code. It runs in local workers with my OS permissions.</label><p class="field-note">This is trusted Python execution, not a sandbox. Registration performs a real forward / backward probe. Changing parameters or shapes requires registering a validated version.</p><button class="btn primary" type="submit">Register in worker</button></form>`)}${S.jobs.filter(j=>j.kind==='register_operator').slice(0,4).map(j=>panel04('Operator probe',`${badge(j.status)} ${esc(j.payload.name)}${j.error?`<p>${esc(j.error)}</p>`:''}`)).join('')}</div>${panel04('Local registry',(S.operatorRegistry?.operators||[]).map(m=>`<div class="ecosystem-model"><div><strong>${esc(m.name)} · v${m.version||1}</strong><p>${m.contracts[''].input_shape.join(' × ')} → ${m.contracts[''].output_shape.join(' × ')}<br>${m.enabled?'Enabled':'Disabled'} · ${m.id.slice(0,8)}</p></div><div><button class="btn small" data-use-operator="${m.id}" ${m.enabled?'':'disabled'}>Insert after selection</button><button class="btn small" data-disable-operator="${m.id}" ${m.enabled?'':'disabled'}>Disable</button></div></div>`).join('')||'<p>No registered operators yet.</p>')}</div>`;$('#operator-register').onsubmit=fire(async e=>{e.preventDefault();const f=new FormData(e.currentTarget);await api('/operators','POST',{name:f.get('name'),source:f.get('source'),parameters:JSON.parse(f.get('parameters')),input_shape:String(f.get('input_shape')).split(',').map(Number),trusted_code:f.has('trusted_code')});toast('Operator probe queued');render()});$$('[data-use-operator]').forEach(b=>b.onclick=fire(async()=>{const m=S.operatorRegistry.operators.find(m=>m.id===b.dataset.useOperator);const r=await api('/graph/edit','POST',{ir:S.ir,action:'insert',node_id:S.selected||'input',op:'CustomOperator',config:{operator_id:m.id,parameters:m.parameters}});history();S.ir=r.ir;S.selected=r.inserted;S.positions={};setDirty();await analyze(false);navigate('architecture')}));$$('[data-disable-operator]').forEach(b=>b.onclick=fire(async()=>{await api('/operators/'+b.dataset.disableOperator+'/disable','POST',{});await refreshModels04();render()}));}
const inspector04=renderInspector;renderInspector=function(){inspector04();const n=S.ir.nodes.find(n=>n.id===S.selected);if(!n||!['EcosystemBlock','CustomOperator'].includes(n.op))return;const el=$('#inspector'),spec=S.analysis?.nodes.find(x=>x.id===n.id),asset=S.modelAssets.find(m=>m.id===n.config.asset_id),contract=asset?.contracts?.[n.config.module_path||''],replaceable=contract?.input_shape?.length===3&&contract?.output_shape?.length===3;el.innerHTML=`<div class="inspector-heading"><span class="eyebrow">PROTECTED CONTRACT</span><h3>${esc(n.name||n.op)}</h3></div><div class="panel-body"><p>${esc(n.op)}</p><p class="field-note">${spec?.shape?.join(' × ')} · ${compact(spec?.params)} parameters</p><p class="field-note">Original internals and local weights are preserved. Use a validated replacement to make this boundary editable.</p>${n.op==='EcosystemBlock'&&replaceable?'<button class="btn full-width" id="replace-ecosystem">Preview searchable replacement</button>':''}<button class="btn full-width" data-action="inspect-node">Inspect real tensor</button>${n.op==='EcosystemBlock'?'<button class="btn full-width" id="ecosystem-tree">View original module hierarchy</button>':''}</div>`;$('#ecosystem-tree')?.addEventListener('click',()=>{const asset=S.modelAssets.find(m=>m.id===n.config.asset_id);modal('Original model hierarchy',`<p class="field-note">Read-only PyTorch module tree. Select a supported IR boundary for local editing or replacement.</p><div class="module-tree-view">${(asset?.module_tree||[]).map(m=>`<div style="padding-left:${Math.min(8,m.path.split('.').length)*12}px"><code>${esc(m.path||'Model')}</code><span>${esc(m.type)}</span></div>`).join('')}</div>`)});$('#replace-ecosystem')?.addEventListener('click',fire(async()=>{const r=await api('/ecosystem/replacement','POST',{ir:rootGraph(),path:nodePath(n.id),width:32});modal('Review local replacement',`<p>This replaces ${esc(n.name||n.id)} with an initialized bottleneck module. Other pretrained blocks keep their local weights.</p><div class="compare-grid">${compareGraph04(rootGraph(),r.ir)}${compareGraph04(r.ir,rootGraph())}</div><p class="field-note">Output shape is preserved. Model quality must be verified by training or evaluation.</p><button class="btn primary" id="apply-replacement">Apply replacement</button>`);$('#apply-replacement').onclick=fire(async()=>{history();S.ir=r.ir;S.modulePath=[];S.selected=n.id;S.positions={};setDirty();await analyze(false);$('#modal').close();navigate('architecture')})}));bindActions();};
const architecture04=renderArchitecture;renderArchitecture=function(){architecture04();const actions=$('.heading-actions')||$('.page-heading .actions');actions?.insertAdjacentHTML('afterbegin',btn('Copilot','open-copilot','orbit')+btn('3D CAD','open-cad','layers'));if(S.agentCanvasPreview){const c=S.agentCanvasPreview.compiled;$('#canvas')?.insertAdjacentHTML('afterbegin',`<div class="agent-canvas-banner"><strong>Pending: ${esc(c.plan.title)}</strong><span>Current draft stays unchanged until approval</span><button class="btn small" data-action="open-copilot">Review plan</button></div>`);for(const step of c.plan.steps){const id=step.node_id.split('/')[0];$$('[data-node]').filter(n=>n.dataset.node===id).forEach(n=>n.classList.add('agent-pending-node'))}}if(S.analysis?.static_macs_available===false){const cards=$$('.metric-value');if(cards[1])cards[1].innerHTML='—<small> MACs</small>'}$$('[data-registered-operator]').forEach(b=>b.onclick=fire(()=>insertOperator04(S.operatorRegistry.operators.find(m=>m.id===b.dataset.registeredOperator))));bindActions();};
const components04=renderComponents;renderComponents=function(){return components04()+`<div class="library-group">YOUR ECOSYSTEM</div><button class="component ecosystem-component" data-action="open-ecosystem">${opIcon('EcosystemBlock')}<span>Import model</span><span>↗</span></button><button class="component ecosystem-component" data-action="open-operators">${opIcon('CustomOperator')}<span>Custom operators</span><span>↗</span></button>${(S.operatorRegistry?.operators||[]).filter(m=>m.enabled).map(m=>`<button class="component" data-registered-operator="${m.id}">${opIcon('CustomOperator')}<span>${esc(m.name)}</span><span>+</span></button>`).join('')}`};
const settings04=renderSettings;renderSettings=function(){settings04();$('#page').insertAdjacentHTML('beforeend',`<div class="page-content">${panel04('Architecture Agent',`<p>Connect your own API key and a tool-calling model. Credentials are session-only.</p><button class="btn" data-action="agent-settings">Configure Copilot</button>`)}</div>`);bindActions()};
function renderCAD(){S.cadViewer?.dispose();S.cadViewer=null;$('#page').innerHTML=heading('NEURAL SPACE','Interactive Neural CAD','Orbit, inspect and arrange a real 3D architecture scene.',btn('Save scene','cad-save','save')+btn('Export PNG','cad-png','download')+btn('Paper editor','cad-paper','layout'))+`<div class="cad-workspace"><aside class="cad-tree"><span class="eyebrow">MODEL HIERARCHY</span><button id="cad-up" class="btn small">↑ ${S.modulePath.length?'Parent module':'Model root'}</button><p class="field-note">${esc(['Model',...S.modulePath.map(p=>typeof p==='string'?p:p.id||'Module')].join(' / '))}</p>${S.ir.nodes.map(n=>`<button class="cad-tree-node" data-cad-node="${esc(n.id)}"><span>${esc(n.name||n.op)}</span><small>${esc(n.id)}</small>${n.op==='Module'?'<b>↳ Enter</b>':''}</button>`).join('')}<p class="field-note">Drag: orbit<br>Right drag: pan<br>Wheel: zoom<br>Click: inspect<br>Gizmo: move selected block<br>Double-click module: enter</p><button id="cad-reset" class="btn small">Auto layout</button></aside><div id="cad-viewport"><div class="cad-loading">Creating WebGL scene…</div></div><aside id="cad-inspector" class="cad-detail"><span class="eyebrow">INSPECT A BLOCK</span><p>Select a module to see its tensor contract.</p></aside></div>`;$('#cad-up').onclick=async()=>{if(S.modulePath.length)await exitModule(S.modulePath.length-1);navigate('cad')};let instanceToken={};S.cadToken=instanceToken;import('/static/cad.js').then(m=>{if(S.page!=='cad'||S.cadToken!==instanceToken)return;S.cadViewer=m.createCAD($('#cad-viewport'),S.ir,S.analysis,S.project.cad_scene||{},id=>{S.selected=id;const n=S.ir.nodes.find(n=>n.id===id),spec=S.analysis?.nodes.find(n=>n.id===id);if(!n)return;$('#cad-inspector').innerHTML=`<span class="eyebrow">${esc(n.op)}</span><h3>${esc(n.name||n.id)}</h3><p>${esc(spec?.shape?.join(' × ')||'')}</p><p>${compact(spec?.params)} parameters</p><pre>${esc(JSON.stringify(n.config,null,2))}</pre>${n.op==='Module'?'<button class="btn" id="cad-enter">Enter module</button>':''}<button class="btn" id="cad-edit">Edit in 2D</button>`;$('#cad-enter')?.addEventListener('click',async()=>{await enterModule(id);navigate('cad')});$('#cad-edit').onclick=()=>navigate('architecture')},async id=>{if(S.ir.nodes.find(n=>n.id===id)?.op==='Module'){await enterModule(id);navigate('cad')}});$('#cad-reset').onclick=()=>S.cadViewer.reset()}).catch(e=>{$('#cad-viewport').innerHTML=`<div class="cad-loading">WebGL could not start: ${esc(e.message)}</div>`})}
Object.assign(ACTIONS,{'agent-settings':copilotSettings,'open-copilot':()=>navigate('copilot'),'open-cad':()=>navigate('cad'),'open-ecosystem':async()=>{await refreshModels04();navigate('ecosystem')},'open-operators':async()=>{await refreshModels04();navigate('operators')},'refresh-models':async()=>{await refreshModels04();render()},'cad-paper':async()=>{S.exportMode='2d';await openFigure()},'cad-save':async()=>{if(!S.cadViewer)throw Error('Scene is not ready');const r=await api('/cad/scenes','POST',{project_id:S.project.id,document:S.cadViewer.document()});S.project.cad_scene=r.cad_scene;toast('3D scene saved')},'cad-png':()=>{if(!S.cadViewer)throw Error('Scene is not ready');S.cadViewer.png()}});
const init04=init;init=async function(){await Promise.all([refreshModels04(),api('/copilot/config').then(c=>S.agentConfig=c)]);await init04();const nav=$('nav');nav.insertAdjacentHTML('afterbegin',`<button class="nav-item" data-page="copilot">${icon('orbit')}<span>Architecture Copilot</span><span class="pill">AI</span></button>`);nav.insertAdjacentHTML('beforeend',`<button class="nav-item" data-page="ecosystem">${icon('layers')}<span>Model Ecosystem</span></button><button class="nav-item" data-page="operators">${icon('code')}<span>Custom Operators</span></button><button class="nav-item" data-page="cad">${icon('graph')}<span>Neural CAD</span></button>`);$$('[data-page]').forEach(b=>{b.setAttribute('aria-label',titles[b.dataset.page]||b.dataset.page);b.title=titles[b.dataset.page]||b.dataset.page});hydrate();$$('[data-page=copilot],[data-page=cad],[data-page=ecosystem],[data-page=operators]').forEach(b=>b.onclick=fire(async()=>{if(['ecosystem','operators'].includes(b.dataset.page))await refreshModels04();navigate(b.dataset.page)}));};

function outcomePanel04(){const runs=S.jobs.filter(j=>j.kind==='train'&&j.status==='completed'&&j.payload.project_id===S.project.id),options=runs.map(j=>`<option value="${j.id}">${j.id.slice(0,8)} · ${j.device} · AMP ${!!j.amp_effective} · ${j.payload.epochs} epochs</option>`).join('');return panel04('Verify observed optimization',`<form id="optimization-outcome"><label class="field"><span>Baseline run</span><select name="baseline_id">${options}</select></label><label class="field"><span>Optimized run</span><select name="variant_id">${options}</select></label><button class="btn" type="submit" ${runs.length<2?'disabled':''}>Compare real memory & accuracy</button><p class="field-note">Requires two completed runs with the same dataset, split, seed, epoch count, device and effective optimizer batch. Default target: 30% less peak VRAM, at most 1 percentage point accuracy loss.</p></form><div id="optimization-outcome-result"></div>`)}
function bindOutcome04(){$('#optimization-outcome')?.addEventListener('submit',fire(async e=>{e.preventDefault();const r=await api('/copilot/optimization-report','POST',Object.fromEntries(new FormData(e.currentTarget)));$('#optimization-outcome-result').innerHTML=`<div class="agent-warning">${r.comparable?'Matching recorded protocol':'Protocol differs: '+esc(r.mismatches.join(', '))}<br>Memory: ${fmt(r.baseline_peak_mb,2)} → ${fmt(r.variant_peak_mb,2)} MB<br>Observed reduction: ${pct(r.memory_reduction)}<br>Held-out accuracy: ${pct(r.baseline_test_accuracy)} → ${pct(r.variant_test_accuracy)}<br>Memory target: ${r.memory_target_observed?'Observed':'Not verified'}<br>Quality tolerance: ${r.quality_preservation_observed?'Observed':'Not verified'}</div><p class="field-note">${esc(r.evidence)}</p>`}))}

const loadProject04=loadProject;loadProject=async function(p){localStorage.setItem('nf-project',p.id);if(S.agentPreview?.project_id!==p.id){S.agentPreview=null;S.agentCanvasPreview=null}return loadProject04(p)};

const train04=configureTrain;configureTrain=function(candidate=null,sourceJob=null){train04(candidate,sourceJob);if(candidate)return;const form=$('#train-form');for(const [name,value] of Object.entries(S.project.training_defaults||{})){const field=form?.elements.namedItem(name);if(!field)continue;if(field.type==='checkbox')field.checked=!!value;else field.value=value}};

init();
